"""
    The tweet argument is a dict. So get 'entities' key or return a empty dict.
    This is required for the second .get() to not throw a error where we try to
    get 'hashtags'
    """
def get_hashtags(tweet: dict) -> list {
    entities = tweet.get('entities', {});
    hashtags = entities.get('hashtags', []);
    return [("#" + tag['text']) for tag in hashtags];
}

test_blocks:
test "t0" {
    assert (get_hashtags(`dict()) == `list());;
}

test "t1" {
    assert (get_hashtags({'entities': {}}) == `list());;
}

test "t2" {
    assert (get_hashtags({'entities': {'hashtags': []}}) == []);;
}

test "t3" {
    assert (get_hashtags({}) == []);;
}

test "t4" {
    assert (
        get_hashtags({'entities': {'hashtags': [{'text': 'abc'}, {'text': '123'}]}})
        == ['#abc', '#123']
    );;
}

test "t5" {
    assert (get_hashtags({}) == []);;
}

test "t6" {
    assert (get_hashtags({'entities': {'hashtags': []}}) == `list());;
}
